8 | 
9 |   logger: ScopedLogger;
10 |   private readonly llmProvider: LLMProvider;
11 | 
12 |   constructor(config: { maxTokens: number; maxOutputTokens: number; llmProvider: LLMProvider }) {
13 |     this.maxTokens = config.maxTokens;
14 |     this.maxOutputTokens = config.maxOutputTokens;
15 |     this.llmProvider = config.llmProvider;
16 |     this.logger = new ScopedLogger("Compaction");
17 |   }
18 | 
19 |    getToken(history: Message[]){
20 |     const totalUsed = this.calculateTotalUsage(history);
21 |     const usableLimit = this.maxTokens - this.maxOutputTokens;
22 |     console.log(totalUsed)
23 |     return {
24 |       totalUsed,
25 |      usableLimit:usableLimit*this.triggerRatio
26 |     }
27 |   }
28 | 
29 |   /**
30 |    * 核心入口：检查并执行压缩
31 |    * @param history 原始历史记录
32 |    * @param summarizer 外部注入的 LLM 摘要执行器
33 |    */
34 |   /**
35 |    * 性能优化：构建 tool_call_id 到 assistant 索引的映射表
36 |    * 时间复杂度：O(n)，其中 n 是 history 的长度
37 |    * @returns Map<tool_call_id, assistant_index>
38 |    */
39 |   private buildToolCallToAssistantIndex(messages: Message[]): Map<string, number> {
40 |     const index = new Map<string, number>();
41 | 
42 |     // 遍历所有消息，记录每个 tool_call_id 对应的 assistant 索引
43 |     for (let i = 0; i < messages.length; i++) {
44 |       const msg = messages[i];
45 |       if (msg.role === 'assistant' && msg.tool_calls) {
46 |         for (const call of msg.tool_calls) {
47 |           if (call.id) {
48 |             index.set(call.id, i);
49 |           }
50 |         }
51 |       }
52 |     }
53 | 
54 |     return index;
55 |   }
56 | 
57 |   /**
58 |    * 性能优化：构建消息列表中 tool 消息的索引映射
59 |    * 时间复杂度：O(m)，其中 m 是 messages 的长度
60 |    * @returns Map<tool_call_id, message>
61 |    */
62 |   private buildToolMessageMap(messages: Message[]): Map<string, Message> {
63 |     const map = new Map<string, Message>();
64 | 
65 |     for (const msg of messages) {
66 |       if (msg.role === 'tool' && msg.tool_call_id) {
67 |         map.set(msg.tool_call_id, msg);
68 |       }
69 |     }
70 | 
71 |     return map;
72 |   }
73 | 
74 |  
75 | 
76 |   async compact(history: Message[]): Promise<{
77 |     isCompacted: boolean,
78 |     summaryMessage: Message | null,
79 |     list: Message[]
80 |   }> {
81 |     const totalUsed = this.calculateTotalUsage(history);
82 |     const usableLimit = this.maxTokens - this.maxOutputTokens;
83 |     const KEEP_RECENT_COUNT = 6;
84 |     // 如果没达到 92% 的阈值，直接返回原数据
85 |     if (totalUsed < usableLimit * this.triggerRatio || history.length <= KEEP_RECENT_COUNT) {
86 |       return {
87 |         isCompacted: false,
88 |         summaryMessage: null,
89 |         list: history
90 |       };
91 |     }
92 | 
93 | 
94 | 
95 |     this.logger.info(
96 |       `[Compaction] 触发压缩。当前 Token: ${totalUsed}, 阈值: ${Math.floor(usableLimit * this.triggerRatio)}`
97 |     );
98 | 
99 |     let activeMessages = history.slice(-KEEP_RECENT_COUNT); // 保护区
100 |     let pendingMessages = history.slice(0, -KEEP_RECENT_COUNT); // 待压缩区
101 | 
102 |     // 限制保护区的最大膨胀倍数（防止从 6 条膨胀到 100+ 条）
103 |     const MAX_ACTIVE_SIZE = KEEP_RECENT_COUNT * 2;
104 | 
105 |     // 检查保护区的所有 tool 消息，确保它们的配对 assistant 以及所有相关的 tool 回复都被保留
106 |     // 需要处理多个 assistant 的情况（连续多次工具调用）
107 | 
108 |     // 性能优化：一次性构建所有索引，避免 O(n²) 的多次查找
109 |     // 时间复杂度：O(n + m + k)，其中 n=history长度，m=pending长度，k=active长度
110 |     const toolCallToAssistantIndex = this.buildToolCallToAssistantIndex(history);
111 |     const pendingToolMap = this.buildToolMessageMap(pendingMessages);
112 |     const activeToolMap = this.buildToolMessageMap(activeMessages);
113 | 
114 |     const toolMessagesInActive = activeMessages.filter(m =>
115 |       m.role === 'tool' && m.tool_call_id  // 过滤掉无效的 tool_call_id
116 |     );
117 | 
118 |     if (toolMessagesInActive.length > 0) {
119 |       // 收集所有需要保留的 assistant 消息和需要重新排序的 tool 回复
120 |       // 修复：将 tool 回复与对应的 assistant 分组，确保消息顺序正确
121 |       const assistantsToKeep: Map<string, { message: Message; index: number; tools: Message[] }> = new Map();
122 |       // 跟踪从 pendingMessages 移到 toolsToKeep 的 tool_call_id
123 |       const movedToolCallIds = new Set<string>();
124 | 
125 |       // 计算分割点，用于判断 assistant 在哪个区域
126 |       // history[:splitPoint] = pendingMessages
127 |       // history[splitPoint:] = activeMessages
128 |       const splitPoint = history.length - KEEP_RECENT_COUNT;
129 | 
130 |       // 修复：识别唯一需要处理的 assistant 索引
131 |       // 这确保我们只处理每个 assistant 一次，但会收集该 assistant 的所有 tools
132 |       const uniqueAssistantIndices = new Set<number>();
133 |       for (const toolMessage of toolMessagesInActive) {
134 |         const toolCallId = toolMessage.tool_call_id;
135 |         if (!toolCallId) continue;
136 |         const assistantIndex = toolCallToAssistantIndex.get(toolCallId);
137 |         if (assistantIndex !== undefined) {
138 |           uniqueAssistantIndices.add(assistantIndex);
139 |         }
140 |       }
141 | 
142 |       // 为每个唯一的 assistant 处理一次，收集其所有 tools
143 |       for (const assistantIndex of uniqueAssistantIndices) {
144 |         // 从 history 中获取 assistant 消息
145 |         const assistantMessage = history[assistantIndex];
146 |         if (!assistantMessage || !assistantMessage.tool_calls || assistantMessage.tool_calls.length === 0) {
147 |           continue;
148 |         }
149 | 
150 |         const assistantKey = assistantIndex.toString();
151 |         const toolCalls = assistantMessage.tool_calls?.filter(call => call.id) || [];
152 | 
153 |         // 收集该 assistant 的所有 tools（从两个区域按 tool_calls 顺序收集）
154 |         const allTools: Message[] = [];
155 |         for (const toolCall of toolCalls) {
156 |           // 先检查 active 区域，再检查 pending 区域
157 |           let toolMessage = activeToolMap.get(toolCall.id);
158 |           if (!toolMessage) {
159 |             toolMessage = pendingToolMap.get(toolCall.id);
160 |             if (toolMessage) {
161 |               movedToolCallIds.add(toolCall.id); // 跟踪从 pending 移动的 tool
162 |             }
163 |           }
164 |           if (toolMessage) {
