191 |         );
192 |       }
193 | 
194 |       // 将需要保留的 assistant 和 tool 回复按正确顺序加入保护区
195 |       if (assistantsToKeep.size > 0) {
196 |         // 按索引排序 assistants（保持原始顺序）
197 |         const sortedAssistantsWithTools = Array.from(assistantsToKeep.values())
198 |           .sort((a, b) => a.index - b.index);
199 | 
200 |         // 从 pendingMessages 中移除这些 assistants（如果它们在 pendingMessages 中）
201 |         // 同时移除已移动的 tool 消息
202 |         // 修复：使用 splitPoint 而不是 pendingMessages.length
203 |         // item.index 是原 history 数组的索引，需要与 splitPoint 比较
204 |         const indicesToRemove = Array.from(assistantsToKeep.values())
