215 |           });
216 |         }
217 | 
218 |         // 构建新的 activeMessages，将每个 assistant 与它的 tools 交错排列
219 |         // 正确的结构应该是：Assistant1, Tool1, Tool2, Assistant2, Tool3, Tool4, ...
220 |         const newActiveMessages: Message[] = [];
221 | 
222 |         for (const { message: assistantMsg, tools: assistantTools } of sortedAssistantsWithTools) {
223 |           newActiveMessages.push(assistantMsg);
224 |           newActiveMessages.push(...assistantTools);
225 |         }
226 | 
227 |         // 添加剩余的 activeMessages
228 |         newActiveMessages.push(...activeMessages);
229 | 
230 |         // 检查是否超过最大限制
231 |         if (newActiveMessages.length > MAX_ACTIVE_SIZE) {
232 |           this.logger.warn(
233 |             `[Compaction] 保护区膨胀：从 ${KEEP_RECENT_COUNT} 条增长到 ${newActiveMessages.length} 条` +
234 |             `(超过最大限制 ${MAX_ACTIVE_SIZE})，将进行裁剪`
235 |           );
236 | 
237 |           // 计算 assistants 和 tools 的总消息数
238 |           const totalAssistantsAndTools = sortedAssistantsWithTools.reduce(
239 |             (sum, item) => sum + 1 + item.tools.length, 0);
240 | 
241 |           // 裁剪：保留前面的 assistants 和 tools，裁剪后面的原始 activeMessages
242 |           const overflow = newActiveMessages.length - MAX_ACTIVE_SIZE;
243 |           if (overflow > 0 && totalAssistantsAndTools < MAX_ACTIVE_SIZE) {
244 |             // 可以安全地裁剪后面的消息
245 |             newActiveMessages.length = MAX_ACTIVE_SIZE;
246 |           }
247 |         }
248 | 
249 |         activeMessages = newActiveMessages;
250 | 
251 |         // 计算统计信息
252 |         const totalAssistants = sortedAssistantsWithTools.length;
253 |         const totalTools = sortedAssistantsWithTools.reduce((sum, item) => sum + item.tools.length, 0);
254 | 
255 |         this.logger.info(
256 |           `[Compaction] 已将 ${totalAssistants} 个 assistant 和 ${totalTools} 个 tool 回复移到保护区` +
257 |           `（保护区大小：${activeMessages.length}）`
258 |         );
259 |       }
260 |     }
261 | 
262 |     // 3. 提取之前的摘要（如果存在）
263 |     let previousSummary = "";
264 |     if (pendingMessages.length > 0 && pendingMessages[0].type === "summary") {
265 |       previousSummary = pendingMessages[0].content;
266 |       pendingMessages = pendingMessages.slice(1);
267 |     }
268 | 
269 |     // 4. 将待压缩的消息序列化为文本
270 |     // 特别处理：将 tool 消息与其 result 格式化，方便 LLM 理解
271 |     const textToSummarize = pendingMessages
272 |       .map((m) => {
273 |         const prefix = m.type ? `[${m.role}:${m.type}]` : `[${m.role}]`;
274 |         // 如果内容过长（如巨大的代码输出），在摘要前进行初步截断
275 |         const content =
276 |           m.content.length > 2000
277 |             ? m.content.slice(0, 1000) + "...(省略)..."
278 |             : m.content;
279 |         return `${prefix}: ${content}`;
280 |       })
281 |       .join("\n");
282 | 
283 |     // 5. 执行异步摘要
284 |     try {
285 |       const newSummaryContent = await this.summarizer(
286 |         textToSummarize,
287 |         previousSummary,
288 |       );
289 | 
290 |       const summaryMessage: Message = {
291 |         role: "system",
292 |         type: "summary",
293 |         content: `[Historical Memory Snapshot]:\n${newSummaryContent}`,
294 |       };
295 | 
296 |       // 6. 重组历史
297 |       const newHistory = [summaryMessage, ...activeMessages];
298 | 
299 |       return {
300 |         isCompacted: true,
301 |         summaryMessage,
302 |         list: newHistory
303 |       };
304 |     } catch (error) {
305 |       const errorMsg = error instanceof Error ? error.message : String(error);
306 |       this.logger.error(`[Compaction] 摘要生成失败: ${errorMsg}`);
307 |       return {
308 |         isCompacted: true,
309 |         summaryMessage: null,
310 |         list: history.slice(0, history.length - KEEP_RECENT_COUNT)
311 |       };
312 |     }
313 |   }
314 | 
315 |   /**
316 |    * 计算整个对话数组的 Token 用量
317 |    */
318 |   public calculateTotalUsage(messages: Message[]): number {
319 |     return messages.reduce((acc, m) => {
320 |       // 每条消息基础开销 4 tokens (role, name, newline)
321 |       return acc + this.estimate(JSON.stringify(m)) + 4;
322 |     }, 0);
323 |   }
324 | 
325 |   /**
326 |    * 估算单段文本的 Token
327 |    */
328 |   private estimate(text: string): number {
329 |     if (!text) return 0;
330 |     return Math.ceil(
331 |       text.length/4,
332 |     );
333 |   }
