5 | 
6 | import { typedEventBus, createLoggingMiddleware } from './event-bus';
7 | import { Message } from '../providers/base';
8 | 
9 | // ==================== 现有 SessionManager 的事件化改造 ====================
10 | 
11 | /**
12 |  * 事件化的 SessionManager 类
13 |  * 在现有功能基础上添加事件发布
14 |  */
15 | export class SessionManagerWithEvents {
16 |   private sessionId: string;
17 |   private messageList: Message[] = [];
18 | 
19 |   constructor(sessionId: string) {
20 |     this.sessionId = sessionId;
21 |     
22 |     // 订阅与自己相关的事件
23 |     this.setupEventListeners();
24 |     
25 |     // 添加监控中间件
26 |     this.setupMonitoring();
27 |   }
28 | 
29 |   /**
30 |    * 设置事件监听器
31 |    */
32 |   private setupEventListeners(): void {
33 |     // 监听自己的消息添加事件
34 |     typedEventBus.on('session.message.added', (data) => {
35 |       if (data.sessionId === this.sessionId) {
36 |         console.log(`[Session ${this.sessionId}] 收到新消息:`, data.message.content?.substring(0, 50));
37 |       }
38 |     });
39 | 
40 |     // 监听压缩事件
41 |     typedEventBus.on('session.compaction.completed', (data) => {
42 |       if (data.sessionId === this.sessionId) {
43 |         console.log(`[Session ${this.sessionId}] 压缩完成，压缩了 ${data.compressedCount} 条消息`);
44 |       }
45 |     });
46 | 
47 |     // 监听错误事件
48 |     typedEventBus.on('session.error', (data) => {
49 |       if (data.sessionId === this.sessionId) {
50 |         console.error(`[Session ${this.sessionId}] 错误:`, data.error.message);
51 |       }
52 |     });
53 |   }
54 | 
55 |   /**
56 |    * 设置监控
57 |    */
58 |   private setupMonitoring(): void {
59 |     // 添加会话特定的日志中间件
60 |     typedEventBus.useForEvent('session.message.added', createLoggingMiddleware(`Session-${this.sessionId}`));
61 |   }
62 | 
63 |   /**
64 |    * 添加消息（发布事件）
65 |    */
66 |   async addMessage(message: Message): Promise<void> {
67 |     // 现有业务逻辑
68 |     this.messageList.push(message);
69 |     
70 |     // 发布消息添加事件
71 |     await typedEventBus.emit('session.message.added', {
72 |       sessionId: this.sessionId,
73 |       message,
74 |       timestamp: Date.now(),
75 |       messageCount: this.messageList.length
76 |     });
77 | 
78 |     // 检查是否需要压缩
79 |     await this.checkAndCompact();
80 |   }
81 | 
82 |   /**
83 |    * 获取消息（可能触发压缩）
84 |    */
85 |   async getMessages(): Promise<Message[]> {
86 |     // 现有业务逻辑
87 |     const messages = [...this.messageList];
88 |     
89 |     // 发布消息获取事件
90 |     await typedEventBus.emit('session.messages.retrieved', {
91 |       sessionId: this.sessionId,
92 |       count: messages.length,
93 |       timestamp: Date.now()
94 |     });
95 | 
96 |     return messages;
97 |   }
98 | 
99 |   /**
100 |    * 检查并执行压缩
101 |    */
102 |   private async checkAndCompact(): Promise<void> {
103 |     const tokenCount = this.calculateTokenCount();
104 |     const threshold = 1000; // 示例阈值
105 |     
106 |     if (tokenCount > threshold) {
107 |       // 发布压缩触发事件
108 |       await typedEventBus.emit('session.compaction.triggered', {
109 |         sessionId: this.sessionId,
110 |         tokenCount,
111 |         threshold,
112 |         timestamp: Date.now()
113 |       });
114 | 
115 |       try {
116 |         // 执行压缩逻辑
117 |         const result = await this.performCompaction();
118 |         
119 |         // 发布压缩完成事件
120 |         await typedEventBus.emit('session.compaction.completed', {
121 |           sessionId: this.sessionId,
122 |           summary: result.summary,
123 |           compressedCount: result.compressedCount,
124 |           originalTokenCount: tokenCount,
125 |           compressedTokenCount: result.newTokenCount,
126 |           timestamp: Date.now()
127 |         });
128 |       } catch (error) {
129 |         // 发布压缩失败事件
130 |         await typedEventBus.emit('session.compaction.failed', {
131 |           sessionId: this.sessionId,
132 |           error: error instanceof Error ? error : new Error(String(error)),
133 |           tokenCount,
134 |           timestamp: Date.now()
135 |         });
136 |         
137 |         // 同时发布通用错误事件
138 |         await typedEventBus.emit('session.error', {
139 |           sessionId: this.sessionId,
140 |           error: error instanceof Error ? error : new Error(String(error)),
141 |           operation: 'compaction',
142 |           timestamp: Date.now()
143 |         });
144 |       }
145 |     }
146 |   }
147 | 
148 |   /**
149 |    * 计算 Token 数量（示例）
150 |    */
151 |   private calculateTokenCount(): number {
152 |     return this.messageList.reduce((total, message) => {
153 |       return total + (message.content?.length || 0) * 0.25; // 简单估算
154 |     }, 0);
155 |   }
156 | 
157 |   /**
158 |    * 执行压缩（示例）
159 |    */
160 |   private async performCompaction(): Promise<{
161 |     summary: any;
162 |     compressedCount: number;
163 |     newTokenCount: number;
164 |   }> {
165 |     // 模拟压缩逻辑
166 |     const compressedCount = Math.floor(this.messageList.length * 0.5);
167 |     const summary = {
168 |       content: `压缩了 ${compressedCount} 条消息`,
169 |       timestamp: Date.now()
170 |     };
171 |     
172 |     // 保留部分消息
173 |     this.messageList = this.messageList.slice(-10);
174 |     
175 |     return {
176 |       summary,
177 |       compressedCount,
178 |       newTokenCount: this.calculateTokenCount()
179 |     };
180 |   }
181 | 
182 |   /**
183 |    * 清空会话
184 |    */
185 |   async clear(): Promise<void> {
186 |     const messageCount = this.messageList.length;
187 |     this.messageList = [];
188 |     
189 |     // 发布清空事件
190 |     await typedEventBus.emit('session.cleared', {
191 |       sessionId: this.sessionId,
192 |       clearedCount: messageCount,
193 |       timestamp: Date.now()
194 |     });
195 |   }
196 | 
197 |   /**
198 |    * 获取会话统计信息
199 |    */
200 |   getStats(): {
201 |     messageCount: number;
202 |     tokenCount: number;
203 |     lastActivity?: number;
204 |   } {
205 |     return {
206 |       messageCount: this.messageList.length,
207 |       tokenCount: this.calculateTokenCount(),
208 |       lastActivity: this.messageList.length > 0 ? Date.now() : undefined
209 |     };
210 |   }
211 | }
