213 | // ==================== 监控服务示例 ====================
214 | 
215 | /**
216 |  * 会话监控服务
217 |  * 监听所有会话事件，进行集中监控
218 |  */
219 | export class SessionMonitorService {
220 |   private sessionStats = new Map<string, any>();
221 |   private errorLog: any[] = [];
222 | 
223 |   constructor() {
224 |     this.setupEventHandlers();
225 |   }
226 | 
227 |   /**
228 |    * 设置事件处理器
229 |    */
230 |   private setupEventHandlers(): void {
231 |     // 监控消息添加
232 |     typedEventBus.on('session.message.added', (data) => {
233 |       const d = data as any;
234 |       this.updateSessionStats(d.sessionId, {
235 |         lastMessage: d.timestamp,
236 |         messageCount: d.messageCount
237 |       });
238 |       this.logActivity(`消息添加: ${d.sessionId}`);
239 |     });
240 | 
241 |     // 监控压缩事件
242 |     typedEventBus.on('session.compaction.triggered', (data) => {
243 |       const d = data as any;
244 |       this.logActivity(`压缩触发: ${d.sessionId} (${d.tokenCount}/${d.threshold} tokens)`);
245 |     });
246 | 
247 |     typedEventBus.on('session.compaction.completed', (data) => {
248 |       const d = data as any;
249 |       this.updateSessionStats(d.sessionId, {
250 |         lastCompaction: d.timestamp,
251 |         compressionRate: d.compressedCount
252 |       });
253 |       this.logActivity(`压缩完成: ${d.sessionId}，节省 ${d.originalTokenCount - d.compressedTokenCount} tokens`);
254 |     });
255 | 
256 |     // 监控错误
257 |     typedEventBus.on('session.error', (data) => {
258 |       const d = data as any;
259 |       this.errorLog.push({
260 |         sessionId: d.sessionId,
261 |         error: d.error.message,
262 |         operation: d.operation,
263 |         timestamp: d.timestamp
264 |       });
265 |       console.error(`[Monitor] 会话错误: ${d.sessionId} - ${d.error.message}`);
266 |     });
267 | 
268 |     // 监控清空事件
269 |     typedEventBus.on('session.cleared', (data) => {
270 |       const d = data as any;
271 |       this.sessionStats.delete(d.sessionId);
272 |       this.logActivity(`会话清空: ${d.sessionId} (${d.clearedCount} 条消息)`);
273 |     });
274 |   }
275 | 
276 |   /**
277 |    * 更新会话统计
278 |    */
279 |   private updateSessionStats(sessionId: string, updates: any): void {
280 |     const stats = this.sessionStats.get(sessionId) || {};
281 |     this.sessionStats.set(sessionId, { ...stats, ...updates });
282 |   }
283 | 
284 |   /**
285 |    * 记录活动
286 |    */
287 |   private logActivity(message: string): void {
288 |     console.log(`[Monitor] ${new Date().toISOString()} - ${message}`);
289 |   }
290 | 
291 |   /**
292 |    * 获取监控报告
293 |    */
294 |   getReport(): {
295 |     activeSessions: number;
296 |     totalErrors: number;
297 |     sessionStats: Map<string, any>;
298 |     recentErrors: any[];
299 |   } {
300 |     return {
301 |       activeSessions: this.sessionStats.size,
302 |       totalErrors: this.errorLog.length,
303 |       sessionStats: new Map(this.sessionStats),
304 |       recentErrors: this.errorLog.slice(-10)
305 |     };
306 |   }
307 | }
308 | 
309 | // ==================== 使用示例 ====================
310 | 
311 | async function runIntegrationExample() {
312 |   console.log('🚀 EventBus 与 SessionManager 集成示例\n');
313 | 
314 |   // 创建监控服务
315 |   const monitor = new SessionMonitorService();
316 | 
317 |   // 创建多个会话管理器
318 |   const session1 = new SessionManagerWithEvents('session-001');
319 |   const session2 = new SessionManagerWithEvents('session-002');
320 | 
321 |   // 模拟用户交互
322 |   console.log('=== 模拟用户交互 ===');
323 |   
324 |   await session1.addMessage({
325 |     role: 'user',
326 |     content: '你好，我想了解产品信息'
327 |   });
328 | 
329 |   await session2.addMessage({
330 |     role: 'user',
331 |     content: '我需要技术支持'
332 |   });
333 | 
