15 | export class ReadFileTool extends BaseTool<typeof readFileSchema> {
16 |   name = "read_file";
17 |   description = `Read file content with line numbers.
18 | 
19 | IMPORTANT USAGE GUIDELINES:
20 | - DEFAULT: Read the ENTIRE file by omitting startLine/endLine parameters
21 | - ONLY use range reading for files larger than 500 lines
22 | - If you need to read a file, ALWAYS try reading it completely first
23 | - The tool will return line numbers to help you navigate
24 | - Most files are small enough to read entirely. Avoid premature optimization
25 | 
26 | Path formats supported:
27 | - Relative paths: "src/file.ts", "./src/file.ts"
28 | - Absolute paths: "/home/user/file.ts" (Unix), "C:\\Users\\user\\file.ts" (Windows)
29 | - The tool automatically normalizes paths for cross-platform compatibility`;
30 | 
31 |   schema = readFileSchema;
32 | 
33 |   async execute(args: { filePath: string; startLine?: number; endLine?: number; }): Promise<ToolOutput> {
34 |     const { filePath, startLine, endLine } = args;
35 | 
36 |     // 规范化路径以支持跨平台
37 |     // Windows: D:\work\file.ts -> D:\work\file.ts
38 |     // Unix: /home/user/file.ts -> /home/user/file.ts
39 |     // Relative: src/file.ts -> /current/dir/src/file.ts
40 |     const normalizedPath = filePath.replace(/\\/g, '/');
41 |     const fullPath = path.resolve(process.cwd(), normalizedPath);
42 | 
43 |     // 检查路径是否存在
44 |     if (!fs.existsSync(fullPath)) {
45 |       return {
46 |         metadata: { ok: false, message: 'FILE_NOT_FOUND', filePath },
47 |         output: `Error: File not found at path: ${filePath}\nResolved path: ${fullPath}`,
48 |       };
49 |     }
50 | 
51 |     // 检查路径是否是文件（不是目录）
52 |     const stats = fs.statSync(fullPath);
53 |     if (!stats.isFile()) {
54 |       return {
55 |         metadata: { ok: false, message: 'NOT_A_FILE', pathType: 'directory', filePath },
56 |         output: `Error: Path provided is not a file. It is a directory.\nPath: ${filePath}\nHint: To read a file, specify the full file path including the filename.`,
57 |       };
58 |     }
59 | 
60 |     // 检查是否是二进制文件
61 |     if (await isBinaryFile(fullPath)) {
62 |       return {
63 |         metadata: { ok: false, message: 'BINARY_FILE', filePath },
64 |         output: `Error: Cannot read binary file. Path: ${filePath}`,
